package kr.yunseok.touchmacro;
import org.junit.Test;import static org.junit.Assert.*;
public class WatchGateTest {
 @Test public void reservesBeforeEntryAndBlocksEveryPresentResult(){WatchGate g=new WatchGate(false);assertTrue(g.observe(true,0,2000));g.reserve();assertFalse(g.observe(true,10000,2000));assertTrue(g.blocked());}
 @Test public void oneMissingScanNeverRearms(){WatchGate g=new WatchGate(true);assertFalse(g.observe(false,100,2000));assertTrue(g.blocked());assertFalse(g.observe(true,10000,2000));assertTrue(g.blocked());}
 @Test public void requiresTwoAbsentScansAcrossTimeAndThenNewAppearance(){WatchGate g=new WatchGate(true);assertFalse(g.observe(false,100,2000));assertFalse(g.observe(false,2099,2000));assertTrue(g.blocked());assertFalse(g.observe(false,2100,2000));assertFalse(g.blocked());assertTrue(g.observe(true,2200,2000));}
 @Test public void presenceAndInterruptedContextResetAbsence(){WatchGate g=new WatchGate(true);g.observe(false,0,2000);g.observe(true,1500,2000);g.observe(false,2100,2000);assertTrue(g.blocked());g.interruptAbsence();g.observe(false,8000,2000);assertTrue(g.blocked());}
 @Test public void restoredReservationStartsBlocked(){WatchGate g=new WatchGate(true);assertFalse(g.observe(true,5000,2000));assertTrue(g.blocked());}
 @Test public void profileTimingsAndLockSurviveSave(){WatchConfig p=new WatchConfig();p.startMs=500;p.beforeBackMs=250;p.repeatGapMs=125;p.rearmMs=3000;p.targetPackage="com.example.target";WatchConfig q=new WatchConfig(p.json());q.validate();assertFalse(q.preventDuplicate);assertEquals(p.lockKey(),q.lockKey());assertEquals(125,q.repeatGapMs);assertEquals(250,q.beforeBackMs);Macro m=new Macro();m.steps.add(new Step("WAIT"));m.startDelay=8000;m.gap=2000;Macro prepared=q.prepareMacro(m);assertEquals(0,prepared.startDelay);assertEquals(125,prepared.gap);assertEquals(8000,m.startDelay);}
 @Test(expected=IllegalArgumentException.class) public void rejectsTooShortAbsence(){WatchConfig p=new WatchConfig();p.rearmMs=500;p.validate();}
 @Test public void sixExplicitPrioritiesPreserveTheirOrderAndIndependentLocks(){WatchConfig p=new WatchConfig();for(int i=5;i>=0;i--)p.priorityAreas.add(new WatchArea((i%2)*50,(i/2)*30,(i%2)*50+45,(i/2)*30+25));WatchConfig q=new WatchConfig(p.json());q.validate();assertEquals(6,q.areaCount());assertEquals(50,q.areaConfig(0).rule.left,0);assertEquals(60,q.areaConfig(0).rule.top,0);assertNotEquals(q.areaConfig(0).lockKey(),q.areaConfig(1).lockKey());assertEquals(600000,q.cooldownMs);assertEquals(10,q.intervalSeconds);}
 @Test(expected=IllegalArgumentException.class) public void rejectsOverlappingPriorityBoxes(){WatchConfig p=new WatchConfig();p.priorityAreas.add(new WatchArea(0,0,50,50));p.priorityAreas.add(new WatchArea(25,25,75,75));p.validate();}
 @Test(expected=IllegalArgumentException.class) public void rejectsSeventhPriority(){WatchConfig p=new WatchConfig();for(int i=0;i<7;i++)p.priorityAreas.add(new WatchArea(0,i*10,50,i*10+5));p.validate();}
}
